package mcpserver

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"path/filepath"
	"reflect"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/openclaw/turnwire/internal/identity"
	"github.com/openclaw/turnwire/internal/mailbox"
)

type stubChannel struct {
	input  mailbox.SendInput
	output mailbox.SendOutput
}

func (s *stubChannel) Send(_ context.Context, input mailbox.SendInput) (mailbox.SendOutput, error) {
	s.input = input
	return s.output, nil
}
func (*stubChannel) Receive(context.Context, mailbox.ReceiveInput) (mailbox.ReceiveOutput, error) {
	return mailbox.ReceiveOutput{}, nil
}
func (*stubChannel) Confirm(context.Context, mailbox.ConfirmInput) (mailbox.ConfirmOutput, error) {
	return mailbox.ConfirmOutput{}, nil
}
func (*stubChannel) Inbox(context.Context, mailbox.InboxInput) (mailbox.InboxOutput, error) {
	return mailbox.InboxOutput{}, nil
}
func (*stubChannel) Checkpoint() (identity.Checkpoint, error) { return identity.Checkpoint{}, nil }

type stuckShutdownChannel struct {
	stubChannel
	release chan struct{}
}

func (s *stuckShutdownChannel) Shutdown(context.Context) error {
	<-s.release
	return nil
}

func TestRunBoundsStuckShutdown(t *testing.T) {
	channel := &stuckShutdownChannel{release: make(chan struct{})}
	defer close(channel.release)
	started := time.Now()
	err := run(context.Background(), channel, "test", bytes.NewReader(nil), io.Discard, filepath.Join(t.TempDir(), "state"), 1024, 1, 60, 25*time.Millisecond)
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Run error = %v, want shutdown deadline", err)
	}
	if elapsed := time.Since(started); elapsed > time.Second {
		t.Fatalf("Run took %v, want one bounded shutdown wait", elapsed)
	}
}

func TestSignedMailboxToolsOverInMemoryTransport(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	input := mailbox.SendInput{Destination: "personal", Text: "hello", RequestID: "request-1"}
	want := mailbox.SendOutput{Status: "review_required", MessageID: "message-1", RequestID: "request-1", BodySHA256: "hash", Decision: "review", ReasonCode: "ambiguous", AuditSequence: 3, AuditHead: "head"}
	channel := &stubChannel{output: want}
	serverTransport, clientTransport := mcp.NewInMemoryTransports()
	serverSession, err := New(channel, "test").Connect(ctx, serverTransport, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer serverSession.Close()
	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "test"}, nil)
	clientSession, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer clientSession.Close()
	tools, err := clientSession.ListTools(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	wantNames := []string{"audit_checkpoint", "confirm_delivery", "list_messages", "receive_message", "send_message"}
	gotNames := make([]string, 0, len(tools.Tools))
	for _, tool := range tools.Tools {
		gotNames = append(gotNames, tool.Name)
	}
	if !reflect.DeepEqual(gotNames, wantNames) {
		t.Fatalf("tools=%v", gotNames)
	}
	result, err := clientSession.CallTool(ctx, &mcp.CallToolParams{Name: "send_message", Arguments: input})
	if err != nil {
		t.Fatal(err)
	}
	if result.IsError {
		t.Fatalf("result=%#v", result)
	}
	if len(result.Content) != 0 {
		t.Fatalf("result duplicated structured output into content: %#v", result.Content)
	}
	if !reflect.DeepEqual(channel.input, input) {
		t.Fatalf("input=%#v", channel.input)
	}
	structured, err := json.Marshal(result.StructuredContent)
	if err != nil {
		t.Fatal(err)
	}
	var got mailbox.SendOutput
	if err := json.Unmarshal(structured, &got); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got=%#v want=%#v", got, want)
	}
}

func TestPublicToolErrorRedactsRateLimitDetails(t *testing.T) {
	err := publicToolError(mailbox.ErrRateLimited)
	if got, want := err.Error(), "rate_limited: relay request budget exhausted"; got != want {
		t.Fatalf("publicToolError = %q, want %q", got, want)
	}
}

package mcpserver

import (
	"bytes"
	"context"
	"errors"
	"io"
	"math"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/openclaw/turnwire/internal/identity"
	"github.com/openclaw/turnwire/internal/mailbox"
)

func TestFrameByteLimit(t *testing.T) {
	got, err := frameByteLimit(10)
	if err != nil {
		t.Fatal(err)
	}
	want := frameEnvelopeOverheadBytes + jsonEscapeExpansion*10
	if got != want {
		t.Fatalf("frameByteLimit(10) = %d, want %d", got, want)
	}

	got, err = frameByteLimit(math.MaxInt)
	if err != nil {
		t.Fatal(err)
	}
	if got != math.MaxInt {
		t.Fatalf("overflow-safe frame limit = %d, want %d", got, math.MaxInt)
	}
}

func TestBoundedFrameReaderAcceptsExactCap(t *testing.T) {
	limit, err := frameByteLimit(1)
	if err != nil {
		t.Fatal(err)
	}
	payload := []byte(`"` + strings.Repeat("a", limit-2) + `"`)
	for name, ending := range map[string]string{"LF": "\n", "CRLF": "\r\n"} {
		t.Run(name, func(t *testing.T) {
			frame := append(append([]byte(nil), payload...), ending...)
			reader := newBoundedFrameReadCloser(bytes.NewReader(frame), limit)
			got, err := io.ReadAll(reader)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, frame) {
				t.Fatalf("exact-cap frame changed: got %d bytes, want %d", len(got), len(frame))
			}
		})
	}
}

func TestBoundedFrameReaderRejectsOversizedFrame(t *testing.T) {
	limit, err := frameByteLimit(1)
	if err != nil {
		t.Fatal(err)
	}
	payload := []byte(`"` + strings.Repeat("a", limit-1) + `"` + "\n")
	reader := newBoundedFrameReadCloser(bytes.NewReader(payload), limit)
	if _, err := io.ReadAll(reader); !errors.Is(err, errFrameTooLarge) {
		t.Fatalf("oversized frame error = %v, want %v", err, errFrameTooLarge)
	}
}

func TestBoundedFrameReaderRejectsIncompleteJSONPerFrame(t *testing.T) {
	// Each newline-delimited payload is individually below the frame limit. The
	// first incomplete value must be rejected before any bytes reach the SDK;
	// otherwise its decoder can accumulate subsequent frames without a bound.
	input := []byte("[\n[\n[\n")
	reader := newBoundedFrameReadCloser(bytes.NewReader(input), 1)
	got, err := io.ReadAll(reader)
	if !errors.Is(err, errInvalidJSONFrame) {
		t.Fatalf("incomplete frame error = %v, want %v", err, errInvalidJSONFrame)
	}
	if len(got) != 0 {
		t.Fatalf("reader released %d bytes from an incomplete frame", len(got))
	}
}

func TestBoundedFrameReaderRejectsMultipleJSONValues(t *testing.T) {
	reader := newBoundedFrameReadCloser(bytes.NewReader([]byte("{}{}\n")), 4)
	if _, err := io.ReadAll(reader); !errors.Is(err, errInvalidJSONFrame) {
		t.Fatalf("multiple-value frame error = %v, want %v", err, errInvalidJSONFrame)
	}
}

func TestBoundedFrameReaderRejectsInvalidTextEncoding(t *testing.T) {
	tests := []struct {
		name  string
		frame []byte
		want  error
	}{
		{
			name:  "raw invalid UTF-8",
			frame: []byte{'{', '"', 'x', '"', ':', '"', 0xff, '"', '}', '\n'},
			want:  errInvalidUTF8,
		},
		{
			name:  "lone high surrogate",
			frame: []byte(`{"x":"\uD800"}` + "\n"),
			want:  errInvalidSurrogate,
		},
		{
			name:  "lone low surrogate",
			frame: []byte(`{"x":"\uDC00"}` + "\n"),
			want:  errInvalidSurrogate,
		},
		{
			name:  "mismatched surrogate pair",
			frame: []byte(`{"x":"\uD800\u0041"}` + "\n"),
			want:  errInvalidSurrogate,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			reader := newBoundedFrameReadCloser(bytes.NewReader(test.frame), 1024)
			if _, err := io.ReadAll(reader); !errors.Is(err, test.want) {
				t.Fatalf("frame error = %v, want %v", err, test.want)
			}
		})
	}
}

func TestBoundedFrameReaderAcceptsSurrogatePair(t *testing.T) {
	frame := []byte(`{"x":"\uD83D\uDE00"}` + "\n")
	reader := newBoundedFrameReadCloser(bytes.NewReader(frame), 1024)
	got, err := io.ReadAll(reader)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, frame) {
		t.Fatalf("valid surrogate-pair frame changed: got %q, want %q", got, frame)
	}
}

type countingChannel struct {
	calls atomic.Int32
}

func (t *countingChannel) Send(context.Context, mailbox.SendInput) (mailbox.SendOutput, error) {
	t.calls.Add(1)
	return mailbox.SendOutput{}, nil
}
func (*countingChannel) Receive(context.Context, mailbox.ReceiveInput) (mailbox.ReceiveOutput, error) {
	return mailbox.ReceiveOutput{}, nil
}
func (*countingChannel) Confirm(context.Context, mailbox.ConfirmInput) (mailbox.ConfirmOutput, error) {
	return mailbox.ConfirmOutput{}, nil
}
func (*countingChannel) Inbox(context.Context, mailbox.InboxInput) (mailbox.InboxOutput, error) {
	return mailbox.InboxOutput{}, nil
}
func (*countingChannel) Checkpoint() (identity.Checkpoint, error) { return identity.Checkpoint{}, nil }

func TestRunRejectsInvalidFrameBeforeSDKDecode(t *testing.T) {
	tests := []struct {
		name  string
		frame []byte
		want  error
	}{
		{
			name:  "invalid raw UTF-8",
			frame: []byte{'{', '"', 'j', 's', 'o', 'n', 'r', 'p', 'c', '"', ':', '"', '2', '.', '0', '"', ',', '"', 'x', '"', ':', '"', 0xff, '"', '}', '\n'},
			want:  errInvalidUTF8,
		},
		{
			name:  "lone surrogate",
			frame: []byte(`{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"clientInfo":{"name":"\uD800","version":"1"}}}` + "\n"),
			want:  errInvalidSurrogate,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			channel := &countingChannel{}
			err := Run(context.Background(), channel, "test", bytes.NewReader(test.frame), io.Discard, filepath.Join(t.TempDir(), "state"), 32, 1, 60)
			if !errors.Is(err, test.want) && (err == nil || !strings.Contains(err.Error(), test.want.Error())) {
				t.Fatalf("Run error = %v, want %v", err, test.want)
			}
			if got := channel.calls.Load(); got != 0 {
				t.Fatalf("Send calls = %d, want 0", got)
			}
		})
	}
}

package mcpserver

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"math"
	"reflect"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/openclaw/turnwire/internal/testutil"

	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
)

func TestTransportCallLimit(t *testing.T) {
	for _, test := range []struct {
		model int
		want  int
	}{
		{model: 1, want: 6},
		{model: 8, want: 20},
		{model: math.MaxInt, want: math.MaxInt},
	} {
		got, err := transportCallLimit(test.model)
		if err != nil || got != test.want {
			t.Fatalf("transportCallLimit(%d) = (%d, %v), want (%d, nil)", test.model, got, err, test.want)
		}
	}
	for _, model := range []int{0, -1} {
		if _, err := transportCallLimit(model); err == nil {
			t.Fatalf("transportCallLimit(%d) error = nil, want validation failure", model)
		}
	}
}

func TestDerivedTransportLimitBoundsOutstandingCalls(t *testing.T) {
	limit, err := transportCallLimit(1)
	if err != nil {
		t.Fatal(err)
	}
	var input strings.Builder
	for i := 0; i <= limit; i++ {
		input.WriteString(callFrame(t, float64(i+1), "tools/call"))
	}
	input.WriteString(notificationFrame(t, "notifications/cancelled"))
	output := &lockedWriteCloser{}
	stream := newStaticLimitedStream(input.String(), output, limit)
	t.Cleanup(func() { _ = stream.Close() })

	for i := 0; i < limit; i++ {
		message := mustReadOneMessage(t, stream)
		request, ok := message.(*jsonrpc.Request)
		if !ok || !request.IsCall() {
			t.Fatalf("admitted message %d = %#v, want call", i, message)
		}
	}
	message := mustReadOneMessage(t, stream)
	request, ok := message.(*jsonrpc.Request)
	if !ok || request.Method != "notifications/cancelled" {
		t.Fatalf("message after overload = %#v, want cancellation", message)
	}
	pending, responding := limiterCounts(stream)
	if pending != limit || responding != 0 {
		t.Fatalf("state = pending %d responding %d, want %d/0", pending, responding, limit)
	}
	assertBusyOutput(t, []byte(output.String()), mustID(t, float64(limit+1)))
}

func TestImmediateRequestIDReuseBeforeResponseWriteReturns(t *testing.T) {
	stdin, input := io.Pipe()
	output := newGatedWriteCloser()
	stream := newLimitedStream(stdin, output, 2)
	t.Cleanup(func() {
		_ = stream.Close()
		_ = input.Close()
	})
	id := mustID(t, "reused-id")
	writeAndReadOneMessage(t, input, stream, callFrame(t, id.Raw(), "tools/call"))

	const generations = 100
	for generation := 0; generation < generations; generation++ {
		writeDone := make(chan error, 1)
		go func() { writeDone <- writeResponse(stream, id) }()
		observation := receiveWrite(t, output.visible)
		assertResponseID(t, observation.frame, id)

		if generation+1 < generations {
			message := writeAndReadOneMessage(t, input, stream, callFrame(t, id.Raw(), "tools/call"))
			request, ok := message.(*jsonrpc.Request)
			if !ok || !reflect.DeepEqual(request.ID.Raw(), id.Raw()) {
				t.Fatalf("generation %d reuse = %#v", generation, message)
			}
			pending, responding := limiterCounts(stream)
			if pending != 1 || responding != 1 || pending+responding > stream.maxInFlight {
				t.Fatalf("generation %d state: pending=%d responding=%d", generation, pending, responding)
			}
		}

		close(observation.release)
		if err := <-writeDone; err != nil {
			t.Fatalf("generation %d Write: %v", generation, err)
		}
	}
	pending, responding := limiterCounts(stream)
	if pending != 0 || responding != 0 {
		t.Fatalf("final state: pending=%d responding=%d", pending, responding)
	}
}

func TestIDReuseWaitsForResponseToEnterOutputLane(t *testing.T) {
	stdin, input := io.Pipe()
	output := newGatedWriteCloser()
	stream := newLimitedStream(stdin, output, 2)
	t.Cleanup(func() {
		_ = stream.Close()
		_ = input.Close()
	})
	id := mustID(t, "bounded-reuse")
	writeAndReadOneMessage(t, input, stream, callFrame(t, id.Raw(), "tools/call"))

	writesDone := make(chan error, 2)
	go func() { writesDone <- writeResponse(stream, id) }()
	first := receiveWrite(t, output.visible)

	writeAndReadOneMessage(t, input, stream, callFrame(t, id.Raw(), "tools/call"))
	go func() { writesDone <- writeResponse(stream, id) }()
	waitForLimiterCounts(t, stream, 1, 1)

	inputDone := writePipeFrames(input, callFrame(t, id.Raw(), "tools/call"))
	if _, err := readOneMessage(stream); !errors.Is(err, errDuplicateInFlightRequest) {
		t.Fatalf("same ID while response waits for output lane = %v, want %v", err, errDuplicateInFlightRequest)
	}
	if err := <-inputDone; err != nil {
		t.Fatal(err)
	}
	// The queued response is still pending, so pending plus the response in the
	// output lane remains exactly at the configured cap.
	waitForLimiterCounts(t, stream, 1, 1)

	close(first.release)
	second := receiveWrite(t, output.visible)
	assertResponseID(t, second.frame, id)
	close(second.release)
	for i := 0; i < 2; i++ {
		if err := <-writesDone; err != nil {
			t.Fatalf("response Write %d: %v", i, err)
		}
	}
	pending, responding := limiterCounts(stream)
	if pending != 0 || responding != 0 {
		t.Fatalf("final state: pending=%d responding=%d", pending, responding)
	}
}

func TestRequestLimitedStreamReadsCancellationAtCallCap(t *testing.T) {
	first := mustID(t, float64(1))
	input := callFrame(t, first.Raw(), "tools/call") + notificationFrame(t, "notifications/cancelled")
	output := &lockedWriteCloser{}
	stream := newStaticLimitedStream(input, output, 1)
	t.Cleanup(func() { _ = stream.Close() })

	mustReadOneMessage(t, stream)
	message := mustReadOneMessage(t, stream)
	request, ok := message.(*jsonrpc.Request)
	if !ok || request.Method != "notifications/cancelled" {
		t.Fatalf("second message = %#v, want cancellation", message)
	}
	if err := writeResponse(stream, first); err != nil {
		t.Fatal(err)
	}
	pending, _ := limiterCounts(stream)
	if pending != 0 {
		t.Fatalf("pending calls = %d, want 0", pending)
	}
}

func TestRequestLimitedStreamRejectsOverloadWithoutSDKDispatch(t *testing.T) {
	active := mustID(t, "active")
	overloaded := mustID(t, "overloaded")
	input := callFrame(t, active.Raw(), "tools/call") +
		callFrame(t, overloaded.Raw(), "tools/call") +
		notificationFrame(t, "notifications/cancelled")
	output := &lockedWriteCloser{}
	stream := newStaticLimitedStream(input, output, 1)
	t.Cleanup(func() { _ = stream.Close() })

	first := mustReadOneMessage(t, stream)
	if request, ok := first.(*jsonrpc.Request); !ok || !reflect.DeepEqual(request.ID.Raw(), active.Raw()) {
		t.Fatalf("first message = %#v", first)
	}
	second := mustReadOneMessage(t, stream)
	if request, ok := second.(*jsonrpc.Request); !ok || request.Method != "notifications/cancelled" {
		t.Fatalf("second SDK-visible message = %#v, want cancellation", second)
	}
	assertBusyOutput(t, []byte(output.String()), overloaded)
}

func TestRequestLimitedStreamBoundsNonCallLifetime(t *testing.T) {
	var input strings.Builder
	for i := 0; i <= maxInboundNonCallMessages; i++ {
		input.WriteString(notificationFrame(t, "notifications/cancelled"))
	}
	stream := newStaticLimitedStream(input.String(), &lockedWriteCloser{}, 1)
	t.Cleanup(func() { _ = stream.Close() })
	for i := 0; i < maxInboundNonCallMessages; i++ {
		mustReadOneMessage(t, stream)
	}
	if _, err := readOneMessage(stream); !errors.Is(err, errNonCallBudgetExhausted) {
		t.Fatalf("Read past non-call budget = %v, want %v", err, errNonCallBudgetExhausted)
	}
	if _, err := readOneMessage(stream); !errors.Is(err, io.EOF) {
		t.Fatalf("Read after budget failure = %v, want EOF", err)
	}
}

func TestRequestLimitedStreamAllowsNormalNotifications(t *testing.T) {
	input := notificationFrame(t, "notifications/initialized") +
		notificationFrame(t, "notifications/cancelled") +
		callFrame(t, "after-notifications", "tools/call")
	stream := newStaticLimitedStream(input, &lockedWriteCloser{}, 1)
	t.Cleanup(func() { _ = stream.Close() })
	for _, method := range []string{"notifications/initialized", "notifications/cancelled", "tools/call"} {
		message := mustReadOneMessage(t, stream)
		request, ok := message.(*jsonrpc.Request)
		if !ok || request.Method != method {
			t.Fatalf("message = %#v, want %q", message, method)
		}
	}
}

func TestRequestLimitedStreamCountsInboundResponsesAsNonCalls(t *testing.T) {
	var input strings.Builder
	for i := 0; i <= maxInboundNonCallMessages; i++ {
		input.WriteString(responseFrame(t, float64(i+1)))
	}
	stream := newStaticLimitedStream(input.String(), &lockedWriteCloser{}, 1)
	t.Cleanup(func() { _ = stream.Close() })
	for i := 0; i < maxInboundNonCallMessages; i++ {
		if _, ok := mustReadOneMessage(t, stream).(*jsonrpc.Response); !ok {
			t.Fatalf("message %d is not a response", i)
		}
	}
	if _, err := readOneMessage(stream); !errors.Is(err, errNonCallBudgetExhausted) {
		t.Fatalf("Read past response budget = %v, want %v", err, errNonCallBudgetExhausted)
	}
}

func TestRequestLimitedStreamBudgetsSchemaInvalidCallsBeforeSDK(t *testing.T) {
	// A tools/call without params fails typed tool validation, but it must still
	// consume the transport budget before reaching the SDK.
	input := callFrame(t, "invalid-1", "tools/call") + callFrame(t, "invalid-2", "tools/call")
	stream := newStaticLimitedStream(input, &lockedWriteCloser{}, 2)
	stream.requestBudget = testutil.NewWindowBudget(1, time.Minute)
	t.Cleanup(func() { _ = stream.Close() })

	mustReadOneMessage(t, stream)
	if _, err := readStreamFrame(stream); !errors.Is(err, errRequestBudgetExhausted) {
		t.Fatalf("second invalid call error = %v, want %v", err, errRequestBudgetExhausted)
	}
}

func TestRequestLimitedStreamBudgetsMalformedJSONRPCBeforeSDK(t *testing.T) {
	frame := "{\"jsonrpc\":\"1.0\",\"id\":\"bad\",\"method\":\"tools/call\"}\n"
	if _, err := jsonrpc.DecodeMessage([]byte(strings.TrimSpace(frame))); err == nil {
		t.Fatal("test frame unexpectedly decoded as JSON-RPC")
	}
	stream := newStaticLimitedStream(frame+frame, &lockedWriteCloser{}, 2)
	stream.requestBudget = testutil.NewWindowBudget(1, time.Minute)
	t.Cleanup(func() { _ = stream.Close() })

	if got, err := readStreamFrame(stream); err != nil || string(got) != frame {
		t.Fatalf("first malformed frame = (%q, %v)", got, err)
	}
	if _, err := readStreamFrame(stream); !errors.Is(err, errRequestBudgetExhausted) {
		t.Fatalf("second malformed frame error = %v, want %v", err, errRequestBudgetExhausted)
	}
}

func TestRequestLimitedStreamRejectsBatchBeforeForwarding(t *testing.T) {
	input := batchFrame(t,
		&jsonrpc.Request{ID: mustID(t, "first"), Method: "tools/call"},
		&jsonrpc.Request{ID: mustID(t, "second"), Method: "tools/call"},
	)
	output := &lockedWriteCloser{}
	stream := newStaticLimitedStream(input, output, 2)
	t.Cleanup(func() { _ = stream.Close() })

	if _, err := readStreamFrame(stream); !errors.Is(err, errBatchUnsupported) {
		t.Fatalf("batch error = %v, want %v", err, errBatchUnsupported)
	}
	if output.String() != "" {
		t.Fatalf("rejected batch produced output: %q", output.String())
	}
	pending, responding := limiterCounts(stream)
	if pending != 0 || responding != 0 {
		t.Fatalf("rejected batch changed state: pending=%d responding=%d", pending, responding)
	}
}

func TestRequestLimitedStreamRejectsHugeBatchWithoutParsing(t *testing.T) {
	frame := "[" + strings.Repeat("0,", 3<<20) + "0]\n"
	output := &lockedWriteCloser{}
	stream := newRequestLimitedStream(
		newBoundedFrameReadCloser(strings.NewReader(frame), len(frame)),
		output,
		1,
		testMaxOutputBytes,
		testutil.NewWindowBudget(600, time.Minute),
	)
	t.Cleanup(func() { _ = stream.Close() })

	buffer := make([]byte, 1)
	if n, err := stream.Read(buffer); n != 0 || !errors.Is(err, errBatchUnsupported) {
		t.Fatalf("huge batch Read = (%d, %v), want (0, %v)", n, err, errBatchUnsupported)
	}
	if output.String() != "" {
		t.Fatalf("huge batch produced output: %q", output.String())
	}
}

func TestRequestLimitedStreamRejectsOversizedOutput(t *testing.T) {
	output := &lockedWriteCloser{}
	stream := newRequestLimitedStream(
		newBoundedFrameReadCloser(strings.NewReader(""), 1<<20),
		output,
		1,
		64,
		testutil.NewWindowBudget(600, time.Minute),
	)
	if n, err := stream.Write(bytes.Repeat([]byte("x"), 65)); n != 0 || !errors.Is(err, errOutputTooLarge) {
		t.Fatalf("oversized Write = (%d, %v), want (0, %v)", n, err, errOutputTooLarge)
	}
	if output.String() != "" {
		t.Fatalf("oversized output was forwarded: %q", output.String())
	}
}

func TestRequestLimitedStreamWriteFailureUnblocksReaders(t *testing.T) {
	stdin, input := io.Pipe()
	writeFailure := errors.New("stopped stdout")
	output := &errorWriteCloser{err: writeFailure}
	stream := newLimitedStream(stdin, output, 1)
	tracked := &firstError{}
	stream.reportError = tracked.Record
	t.Cleanup(func() {
		_ = stream.Close()
		_ = input.Close()
	})
	id := mustID(t, float64(1))
	writeAndReadOneMessage(t, input, stream, callFrame(t, id.Raw(), "tools/call"))

	readDone := make(chan error, 1)
	go func() {
		_, err := readOneMessage(stream)
		readDone <- err
	}()
	if err := writeResponse(stream, id); !errors.Is(err, writeFailure) {
		t.Fatalf("Write error = %v, want %v", err, writeFailure)
	}
	select {
	case err := <-readDone:
		if err == nil {
			t.Fatal("blocked Read returned nil error after Write failure")
		}
	case <-time.After(time.Second):
		t.Fatal("blocked Read did not stop after Write failure")
	}
	if !errors.Is(tracked.Err(), writeFailure) {
		t.Fatalf("tracked error = %v, want %v", tracked.Err(), writeFailure)
	}
}

func TestRequestLimitedStreamObservesEOFDuringActiveCall(t *testing.T) {
	id := mustID(t, float64(1))
	stream := newStaticLimitedStream(callFrame(t, id.Raw(), "tools/call"), &lockedWriteCloser{}, 1)
	t.Cleanup(func() { _ = stream.Close() })
	mustReadOneMessage(t, stream)
	if _, err := readOneMessage(stream); !errors.Is(err, io.EOF) {
		t.Fatalf("Read at call cap = %v, want EOF", err)
	}
	if _, err := readOneMessage(stream); !errors.Is(err, io.EOF) {
		t.Fatalf("Read after EOF = %v, want EOF", err)
	}
}

func TestRequestLimitedStreamEOFLeavesOutputLaneOpenForActiveResponse(t *testing.T) {
	id := mustID(t, float64(1))
	output := &lockedWriteCloser{}
	stream := newStaticLimitedStream(callFrame(t, id.Raw(), "tools/call"), output, 1)
	t.Cleanup(func() { _ = stream.Close() })
	mustReadOneMessage(t, stream)
	if _, err := readOneMessage(stream); !errors.Is(err, io.EOF) {
		t.Fatalf("terminal Read = %v, want EOF", err)
	}
	if err := writeResponse(stream, id); err != nil {
		t.Fatalf("active response after input EOF: %v", err)
	}
	assertResponseID(t, []byte(output.String()), id)
	pending, responding := limiterCounts(stream)
	if pending != 0 || responding != 0 {
		t.Fatalf("state after EOF response: pending=%d responding=%d", pending, responding)
	}
}

func TestRequestLimitedStreamCloseDiscardsBufferedFrameRemainder(t *testing.T) {
	stream := newStaticLimitedStream(callFrame(t, "buffered", strings.Repeat("m", 1024)), &lockedWriteCloser{}, 1)
	var first [1]byte
	if n, err := stream.Read(first[:]); n != 1 || err != nil {
		t.Fatalf("first partial Read = (%d, %v), want (1, nil)", n, err)
	}
	if err := stream.Close(); err != nil {
		t.Fatal(err)
	}
	buffer := make([]byte, 2048)
	if n, err := stream.Read(buffer); n != 0 || !errors.Is(err, io.EOF) {
		t.Fatalf("Read after Close = (%d, %v), want (0, EOF)", n, err)
	}
}

func TestResponseQueuedBehindBusyOutputDoesNotRetireID(t *testing.T) {
	active := mustID(t, "active")
	overloaded := mustID(t, "overloaded")
	output := newGatedWriteCloser()
	stream := newStaticLimitedStream(
		callFrame(t, active.Raw(), "tools/call")+callFrame(t, overloaded.Raw(), "tools/call"),
		output,
		1,
	)
	t.Cleanup(func() { _ = stream.Close() })
	mustReadOneMessage(t, stream)

	readDone := make(chan error, 1)
	go func() {
		_, err := readOneMessage(stream)
		readDone <- err
	}()
	busy := receiveWrite(t, output.visible)
	assertBusyOutput(t, busy.frame, overloaded)

	responseDone := make(chan error, 1)
	go func() { responseDone <- writeResponse(stream, active) }()
	waitForLimiterCounts(t, stream, 1, 0)
	if _, _, err := stream.admitFrame([]byte(callFrame(t, active.Raw(), "tools/call"))); !errors.Is(err, errDuplicateInFlightRequest) {
		t.Fatalf("same ID while response queued behind busy = %v, want %v", err, errDuplicateInFlightRequest)
	}

	close(busy.release)
	response := receiveWrite(t, output.visible)
	assertResponseID(t, response.frame, active)
	close(response.release)
	if err := <-responseDone; err != nil {
		t.Fatal(err)
	}
	if err := <-readDone; !errors.Is(err, io.EOF) {
		t.Fatalf("Read after busy output = %v, want EOF", err)
	}
}

func TestRequestLimitedStreamBlockedBusyOutputBoundsReadPath(t *testing.T) {
	stdin, input := io.Pipe()
	output := newGatedWriteCloser()
	stream := newLimitedStream(stdin, output, 1)
	t.Cleanup(func() {
		_ = stream.Close()
		_ = input.Close()
	})
	writeAndReadOneMessage(t, input, stream, callFrame(t, "active", "tools/call"))

	inputDone := writePipeFrames(input,
		callFrame(t, "overloaded", "tools/call")+notificationFrame(t, "notifications/cancelled"),
	)
	firstRead := make(chan streamReadResult, 1)
	go func() {
		message, err := readOneMessage(stream)
		firstRead <- streamReadResult{message: message, err: err}
	}()
	busy := receiveWrite(t, output.visible)
	assertBusyOutput(t, busy.frame, mustID(t, "overloaded"))

	secondRead := make(chan streamReadResult, 1)
	go func() {
		message, err := readOneMessage(stream)
		secondRead <- streamReadResult{message: message, err: err}
	}()
	select {
	case result := <-firstRead:
		t.Fatalf("busy Read returned while output blocked: %#v", result)
	case result := <-secondRead:
		t.Fatalf("serialized Read returned while output blocked: %#v", result)
	case <-time.After(50 * time.Millisecond):
	}

	close(busy.release)
	select {
	case result := <-firstRead:
		request, ok := result.message.(*jsonrpc.Request)
		if result.err != nil || !ok || request.Method != "notifications/cancelled" {
			t.Fatalf("Read after busy = (%#v, %v), want cancellation", result.message, result.err)
		}
	case <-time.After(time.Second):
		t.Fatal("busy Read remained blocked")
	}
	if err := <-inputDone; err != nil {
		t.Fatal(err)
	}
	if err := input.Close(); err != nil {
		t.Fatal(err)
	}
	select {
	case result := <-secondRead:
		if !errors.Is(result.err, io.EOF) {
			t.Fatalf("serialized Read = (%#v, %v), want EOF", result.message, result.err)
		}
	case <-time.After(time.Second):
		t.Fatal("serialized Read remained blocked")
	}
}

func TestRequestLimitedStreamRejectsDuplicateInFlightID(t *testing.T) {
	id := mustID(t, "same")
	input := callFrame(t, id.Raw(), "first") + callFrame(t, id.Raw(), "duplicate")
	stream := newStaticLimitedStream(input, &lockedWriteCloser{}, 2)
	t.Cleanup(func() { _ = stream.Close() })
	mustReadOneMessage(t, stream)
	if _, err := readOneMessage(stream); !errors.Is(err, errDuplicateInFlightRequest) {
		t.Fatalf("duplicate Read = %v, want %v", err, errDuplicateInFlightRequest)
	}
	if _, err := readOneMessage(stream); !errors.Is(err, io.EOF) {
		t.Fatalf("Read after duplicate = %v, want EOF", err)
	}
}

type streamReadResult struct {
	message jsonrpc.Message
	err     error
}

type rawWriteObservation struct {
	frame   []byte
	release chan struct{}
}

type gatedWriteCloser struct {
	visible   chan rawWriteObservation
	closed    chan struct{}
	closeOnce sync.Once
}

func newGatedWriteCloser() *gatedWriteCloser {
	return &gatedWriteCloser{
		visible: make(chan rawWriteObservation, 256),
		closed:  make(chan struct{}),
	}
}

func (w *gatedWriteCloser) Write(p []byte) (int, error) {
	observation := rawWriteObservation{
		frame:   append([]byte(nil), p...),
		release: make(chan struct{}),
	}
	select {
	case w.visible <- observation:
	case <-w.closed:
		return 0, io.ErrClosedPipe
	}
	select {
	case <-observation.release:
		return len(p), nil
	case <-w.closed:
		return 0, io.ErrClosedPipe
	}
}

func (w *gatedWriteCloser) Close() error {
	w.closeOnce.Do(func() { close(w.closed) })
	return nil
}

type lockedWriteCloser struct {
	mu sync.Mutex
	b  bytes.Buffer
}

func (w *lockedWriteCloser) Write(p []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.b.Write(p)
}

func (w *lockedWriteCloser) Close() error { return nil }

func (w *lockedWriteCloser) String() string {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.b.String()
}

type errorWriteCloser struct {
	err error
}

func (w *errorWriteCloser) Write([]byte) (int, error) { return 0, w.err }
func (*errorWriteCloser) Close() error                { return nil }

const testMaxOutputBytes = 8 << 20

func newLimitedStream(input io.Reader, output io.WriteCloser, limit int) *requestLimitedStream {
	return newRequestLimitedStream(newBoundedFrameReadCloser(input, 1<<20), output, limit, testMaxOutputBytes, testutil.NewWindowBudget(600, time.Minute))
}

func newStaticLimitedStream(input string, output io.WriteCloser, limit int) *requestLimitedStream {
	return newLimitedStream(strings.NewReader(input), output, limit)
}

func callFrame(t *testing.T, id any, method string) string {
	t.Helper()
	return messageFrame(t, &jsonrpc.Request{ID: mustID(t, id), Method: method})
}

func notificationFrame(t *testing.T, method string) string {
	t.Helper()
	return messageFrame(t, &jsonrpc.Request{Method: method})
}

func responseFrame(t *testing.T, id any) string {
	t.Helper()
	return messageFrame(t, &jsonrpc.Response{ID: mustID(t, id)})
}

func messageFrame(t *testing.T, message jsonrpc.Message) string {
	t.Helper()
	encoded, err := jsonrpc.EncodeMessage(message)
	if err != nil {
		t.Fatal(err)
	}
	return string(encoded) + "\n"
}

func batchFrame(t *testing.T, messages ...jsonrpc.Message) string {
	t.Helper()
	raw := make([]json.RawMessage, 0, len(messages))
	for _, message := range messages {
		encoded, err := jsonrpc.EncodeMessage(message)
		if err != nil {
			t.Fatal(err)
		}
		raw = append(raw, encoded)
	}
	encoded, err := json.Marshal(raw)
	if err != nil {
		t.Fatal(err)
	}
	return string(encoded) + "\n"
}

func mustID(t *testing.T, raw any) jsonrpc.ID {
	t.Helper()
	switch value := raw.(type) {
	case int:
		raw = float64(value)
	case int32:
		raw = float64(value)
	case int64:
		raw = float64(value)
	}
	id, err := jsonrpc.MakeID(raw)
	if err != nil {
		t.Fatal(err)
	}
	return id
}

func writeResponse(stream *requestLimitedStream, id jsonrpc.ID) error {
	encoded, err := jsonrpc.EncodeMessage(&jsonrpc.Response{ID: id})
	if err != nil {
		return err
	}
	_, err = stream.Write(append(encoded, '\n'))
	return err
}

func readStreamFrame(stream *requestLimitedStream) ([]byte, error) {
	buffer := make([]byte, 1<<20)
	n, err := stream.Read(buffer)
	return append([]byte(nil), buffer[:n]...), err
}

func readOneMessage(stream *requestLimitedStream) (jsonrpc.Message, error) {
	frame, err := readStreamFrame(stream)
	if err != nil {
		return nil, err
	}
	message, decoded, err := decodeJSONRPCFrame(frame)
	if err != nil {
		return nil, err
	}
	if !decoded {
		return nil, errors.New("stream did not return one JSON-RPC message")
	}
	return message, nil
}

func mustReadOneMessage(t *testing.T, stream *requestLimitedStream) jsonrpc.Message {
	t.Helper()
	message, err := readOneMessage(stream)
	if err != nil {
		t.Fatal(err)
	}
	return message
}

func writeAndReadOneMessage(t *testing.T, input *io.PipeWriter, stream *requestLimitedStream, frame string) jsonrpc.Message {
	t.Helper()
	done := writePipeFrames(input, frame)
	message := mustReadOneMessage(t, stream)
	if err := <-done; err != nil {
		t.Fatal(err)
	}
	return message
}

func writePipeFrames(input *io.PipeWriter, frames string) <-chan error {
	done := make(chan error, 1)
	go func() {
		_, err := io.WriteString(input, frames)
		done <- err
	}()
	return done
}

func limiterCounts(stream *requestLimitedStream) (int, int) {
	stream.mu.Lock()
	defer stream.mu.Unlock()
	return len(stream.pending), stream.responding
}

func waitForLimiterCounts(t *testing.T, stream *requestLimitedStream, wantPending, wantResponding int) {
	t.Helper()
	deadline := time.Now().Add(time.Second)
	for {
		pending, responding := limiterCounts(stream)
		if pending == wantPending && responding == wantResponding {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("state = pending %d responding %d, want %d/%d", pending, responding, wantPending, wantResponding)
		}
		time.Sleep(time.Millisecond)
	}
}

func receiveWrite(t *testing.T, observations <-chan rawWriteObservation) rawWriteObservation {
	t.Helper()
	select {
	case observation := <-observations:
		return observation
	case <-time.After(time.Second):
		t.Fatal("output write did not start")
		return rawWriteObservation{}
	}
}

func assertResponseID(t *testing.T, frame []byte, want jsonrpc.ID) {
	t.Helper()
	message, decoded, err := decodeJSONRPCFrame(frame)
	if err != nil {
		t.Fatalf("response frame classification: %v", err)
	}
	if !decoded {
		t.Fatalf("response frame = %q", frame)
	}
	response, ok := message.(*jsonrpc.Response)
	if !ok || !reflect.DeepEqual(response.ID.Raw(), want.Raw()) {
		t.Fatalf("response = %#v, want ID %#v", message, want.Raw())
	}
}

func assertBusyOutput(t *testing.T, frame []byte, wantID jsonrpc.ID) {
	t.Helper()
	message, decoded, err := decodeJSONRPCFrame(frame)
	if err != nil {
		t.Fatalf("busy output classification: %v", err)
	}
	if !decoded {
		t.Fatalf("busy output is not JSON-RPC: %q", frame)
	}
	response, ok := message.(*jsonrpc.Response)
	if !ok || !reflect.DeepEqual(response.ID.Raw(), wantID.Raw()) {
		t.Fatalf("busy response for ID %#v not found in %q", wantID.Raw(), frame)
	}
	var wireError *jsonrpc.Error
	if !errors.As(response.Error, &wireError) {
		t.Fatalf("busy response error = %#v", response.Error)
	}
	if wireError.Code != serverBusyCode || wireError.Message != serverBusyMessage || len(wireError.Data) != 0 {
		t.Fatalf("busy error = %#v", wireError)
	}
}

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
