package mcpserver

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"sync"

	"github.com/openclaw/turnwire/internal/strictjson"
)

const (
	// The allowance covers JSON-RPC metadata and non-message MCP methods.
	// Six bytes per input byte covers the worst-case JSON \u00XX representation.
	frameEnvelopeOverheadBytes = 64 * 1024
	jsonEscapeExpansion        = 6
)

var (
	errFrameTooLarge    = errors.New("MCP frame exceeds the configured limit")
	errInvalidJSONFrame = errors.New("MCP frame is not exactly one complete JSON value")
	errInvalidUTF8      = strictjson.ErrInvalidUTF8
	errInvalidSurrogate = strictjson.ErrInvalidSurrogate
)

func frameByteLimit(maxInputBytes int) (int, error) {
	if maxInputBytes <= 0 {
		return 0, errors.New("maximum input bytes must be positive")
	}
	if maxInputBytes > (math.MaxInt-frameEnvelopeOverheadBytes)/jsonEscapeExpansion {
		return math.MaxInt, nil
	}
	return frameEnvelopeOverheadBytes + jsonEscapeExpansion*maxInputBytes, nil
}

// boundedFrameReadCloser validates complete newline-delimited frames before
// exposing any bytes to the SDK's JSON decoder.
type boundedFrameReadCloser struct {
	reader *bufio.Reader
	closer io.Closer
	limit  int

	pending   []byte
	afterErr  error
	closeOnce sync.Once
	closeErr  error
}

func newBoundedFrameReadCloser(input io.Reader, limit int) *boundedFrameReadCloser {
	closer, ok := input.(io.Closer)
	if !ok {
		closer = nopCloser{}
	}
	return &boundedFrameReadCloser{
		reader: bufio.NewReader(input),
		closer: closer,
		limit:  limit,
	}
}

func (r *boundedFrameReadCloser) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	if len(r.pending) == 0 {
		frame, err := r.ReadFrame()
		if err != nil {
			return 0, err
		}
		r.pending = frame
	}

	n := copy(p, r.pending)
	r.pending = r.pending[n:]
	return n, nil
}

// ReadFrame returns exactly one validated JSON frame. It is used by the
// admission layer so classification happens only after the size and strict
// encoding checks have succeeded.
func (r *boundedFrameReadCloser) ReadFrame() ([]byte, error) {
	if r.afterErr != nil {
		return nil, r.afterErr
	}
	frame, afterErr, err := r.readFrame()
	if err != nil {
		r.afterErr = err
		return nil, err
	}
	r.afterErr = afterErr
	return frame, nil
}

func (r *boundedFrameReadCloser) readFrame() ([]byte, error, error) {
	var frame []byte
	for {
		fragment, readErr := r.reader.ReadSlice('\n')
		hasNewline := len(fragment) > 0 && fragment[len(fragment)-1] == '\n'

		if !frameFragmentFits(len(frame), fragment, r.limit, hasNewline) {
			return nil, nil, errFrameTooLarge
		}
		frame = append(frame, fragment...)

		if hasNewline {
			payload := frame[:len(frame)-1]
			if len(payload) > 0 && payload[len(payload)-1] == '\r' {
				payload = payload[:len(payload)-1]
			}
			if len(payload) > r.limit {
				return nil, nil, errFrameTooLarge
			}
			if err := validateStrictJSONText(payload); err != nil {
				return nil, nil, err
			}
			return frame, nil, nil
		}

		switch readErr {
		case nil:
			// ReadSlice returns without a newline only when it fills its buffer.
			continue
		case bufio.ErrBufferFull:
			continue
		case io.EOF:
			if len(frame) == 0 {
				return nil, nil, io.EOF
			}
			if len(frame) > r.limit {
				return nil, nil, errFrameTooLarge
			}
			if err := validateStrictJSONText(frame); err != nil {
				return nil, nil, err
			}
			return frame, io.EOF, nil
		default:
			return nil, nil, fmt.Errorf("read MCP frame: %w", readErr)
		}
	}
}

func frameFragmentFits(current int, fragment []byte, limit int, hasNewline bool) bool {
	if len(fragment) > math.MaxInt-current {
		return false
	}
	total := current + len(fragment)
	if hasNewline {
		payloadBytes := total - 1
		if payloadBytes <= limit {
			return true
		}
		if payloadBytes-limit != 1 {
			return false
		}
		if len(fragment) >= 2 {
			return fragment[len(fragment)-2] == '\r'
		}
		// The newline may be in a fresh fragment after a trailing CR. The
		// exact check after append rejects the frame if that byte was not CR.
		return current > 0
	}

	if total <= limit {
		return true
	}
	// One extra byte is allowed only while it may become the CR in CRLF.
	return total-limit == 1 && len(fragment) > 0 && fragment[len(fragment)-1] == '\r'
}

func validateStrictJSONText(data []byte) error {
	if err := strictjson.ValidateText(data); err != nil {
		return err
	}
	if !json.Valid(data) {
		return errInvalidJSONFrame
	}
	return nil
}

type nopCloser struct{}

func (nopCloser) Close() error { return nil }

func (r *boundedFrameReadCloser) Close() error {
	r.closeOnce.Do(func() {
		r.closeErr = r.closer.Close()
	})
	return r.closeErr
}

package mcpserver

import (
	"context"
	"errors"
	"fmt"
	"io"
	"math"
	"sync"
	"time"

	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/openclaw/turnwire/internal/audit"
	"github.com/openclaw/turnwire/internal/budget"
	"github.com/openclaw/turnwire/internal/identity"
	"github.com/openclaw/turnwire/internal/mailbox"
)

const (
	transportControlHeadroom = 4
	shutdownTimeout          = 10 * time.Second
)

// sdkServerClosingCode is the go-sdk JSON-RPC extension used when a handler
// finishes after its peer has closed the read side. The SDK does not export
// its sentinel, but exposes its structured JSON-RPC error through jsonrpc.
const sdkServerClosingCode int64 = -32004

// Channel exposes the complete signed mailbox protocol.
type Channel interface {
	Send(context.Context, mailbox.SendInput) (mailbox.SendOutput, error)
	Receive(context.Context, mailbox.ReceiveInput) (mailbox.ReceiveOutput, error)
	Confirm(context.Context, mailbox.ConfirmInput) (mailbox.ConfirmOutput, error)
	Inbox(context.Context, mailbox.InboxInput) (mailbox.InboxOutput, error)
	Checkpoint() (identity.Checkpoint, error)
}

type shutdowner interface {
	Shutdown(context.Context) error
}

// New creates the text-only Turnwire MCP server.
func New(channel Channel, version string) *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "turnwire",
		Title:   "Turnwire",
		Version: version,
	}, &mcp.ServerOptions{
		Instructions: "Transfer only signed, policy-guarded text envelopes between configured Turnwire peers. Carry send_message envelopes to receive_message on the destination, then carry acknowledgements back to confirm_delivery.",
		// Override the SDK's historical default logging capability. Turnwire
		// exposes only its explicitly registered tool over MCP.
		Capabilities: &mcp.ServerCapabilities{},
	})

	nonDestructive := false
	openWorld := true
	mcp.AddTool(server, &mcp.Tool{
		Name:        "send_message",
		Title:       "Send message",
		Description: "Guard and sign text for one configured peer. Transfer only a returned released envelope; review_required needs local CLI approval.",
		Annotations: &mcp.ToolAnnotations{
			// Every call appends audit records, so it is neither read-only nor idempotent.
			ReadOnlyHint:    false,
			DestructiveHint: &nonDestructive,
			IdempotentHint:  false,
			OpenWorldHint:   &openWorld,
		},
	}, func(ctx context.Context, _ *mcp.CallToolRequest, input mailbox.SendInput) (*mcp.CallToolResult, mailbox.SendOutput, error) {
		output, err := channel.Send(ctx, input)
		if err != nil {
			return nil, mailbox.SendOutput{}, publicToolError(err)
		}
		return structuredResult(), output, nil
	})

	mcp.AddTool(server, &mcp.Tool{
		Name: "receive_message", Title: "Receive message",
		Description: "Verify a configured peer's signature, run the inbound guards, and commit the accepted message. Return a signed acknowledgement.",
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: false, DestructiveHint: &nonDestructive, IdempotentHint: false, OpenWorldHint: &openWorld},
	}, func(ctx context.Context, _ *mcp.CallToolRequest, input mailbox.ReceiveInput) (*mcp.CallToolResult, mailbox.ReceiveOutput, error) {
		output, err := channel.Receive(ctx, input)
		if err != nil {
			return nil, mailbox.ReceiveOutput{}, publicToolError(err)
		}
		return structuredResult(), output, nil
	})

	mcp.AddTool(server, &mcp.Tool{
		Name: "confirm_delivery", Title: "Confirm delivery",
		Description: "Verify and record the destination peer's signed acknowledgement for a released message.",
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: false, DestructiveHint: &nonDestructive, IdempotentHint: false, OpenWorldHint: &openWorld},
	}, func(ctx context.Context, _ *mcp.CallToolRequest, input mailbox.ConfirmInput) (*mcp.CallToolResult, mailbox.ConfirmOutput, error) {
		output, err := channel.Confirm(ctx, input)
		if err != nil {
			return nil, mailbox.ConfirmOutput{}, publicToolError(err)
		}
		return structuredResult(), output, nil
	})

	mcp.AddTool(server, &mcp.Tool{
		Name: "list_messages", Title: "List messages",
		Description: "Read guard-accepted messages from this endpoint's inbox. Every read is audited.",
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: false, DestructiveHint: &nonDestructive, IdempotentHint: false, OpenWorldHint: &openWorld},
	}, func(ctx context.Context, _ *mcp.CallToolRequest, input mailbox.InboxInput) (*mcp.CallToolResult, mailbox.InboxOutput, error) {
		output, err := channel.Inbox(ctx, input)
		if err != nil {
			return nil, mailbox.InboxOutput{}, publicToolError(err)
		}
		return structuredResult(), output, nil
	})

	type checkpointInput struct{}
	closedWorld := false
	mcp.AddTool(server, &mcp.Tool{
		Name: "audit_checkpoint", Title: "Audit checkpoint",
		Description: "Return a signed checkpoint of the current local audit-chain head for independent storage and reconciliation.",
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: true, DestructiveHint: &nonDestructive, IdempotentHint: false, OpenWorldHint: &closedWorld},
	}, func(_ context.Context, _ *mcp.CallToolRequest, _ checkpointInput) (*mcp.CallToolResult, identity.Checkpoint, error) {
		output, err := channel.Checkpoint()
		if err != nil {
			return nil, identity.Checkpoint{}, publicToolError(err)
		}
		return structuredResult(), output, nil
	})

	return server
}

func structuredResult() *mcp.CallToolResult {
	// A non-nil empty content array prevents the SDK from duplicating the
	// structured payload into text content.
	return &mcp.CallToolResult{Content: []mcp.Content{}}
}

// publicToolError is the privacy boundary for failures returned over MCP.
// Underlying errors may contain provider URLs, environment-variable names,
// filesystem paths, or other guard-side details and must remain local.
func publicToolError(err error) error {
	switch {
	case errors.Is(err, mailbox.ErrInvalidInput):
		return errors.New("invalid_input: invalid turnwire input")
	case errors.Is(err, mailbox.ErrConflict):
		return errors.New("request_conflict: request ID conflicts with an existing message")
	case errors.Is(err, mailbox.ErrBusy):
		return errors.New("busy: relay is at capacity; retry later")
	case errors.Is(err, mailbox.ErrRateLimited):
		return errors.New("rate_limited: relay request budget exhausted")
	case errors.Is(err, mailbox.ErrClosed):
		return errors.New("unavailable: relay is shutting down")
	case errors.Is(err, mailbox.ErrUnauthorized):
		return errors.New("unauthorized: peer identity or signature is invalid")
	case errors.Is(err, audit.ErrQuotaExceeded):
		return errors.New("unavailable: audit log quota reached")
	case errors.Is(err, context.DeadlineExceeded):
		return errors.New("timeout: relay request timed out")
	case errors.Is(err, context.Canceled):
		return errors.New("canceled: relay request canceled")
	default:
		return errors.New("turnwire_error: relay request failed")
	}
}

// Run serves Turnwire over the provided stdin/stdout streams until the
// client disconnects or ctx is canceled. Incoming JSON frames are bounded and
// validated before the MCP SDK decodes them. If t also implements Shutdown,
// Run starts that shutdown as soon as transport teardown is observed and waits
// for both the MCP session and relay workers before returning.
func Run(ctx context.Context, channel Channel, version string, stdin io.Reader, stdout io.Writer, budgetDir string, maxInputBytes, maxConcurrent, maxRequestsPerMinute int) error {
	return run(ctx, channel, version, stdin, stdout, budgetDir, maxInputBytes, maxConcurrent, maxRequestsPerMinute, shutdownTimeout)
}

func run(ctx context.Context, channel Channel, version string, stdin io.Reader, stdout io.Writer, budgetDir string, maxInputBytes, maxConcurrent, maxRequestsPerMinute int, shutdownTimeout time.Duration) (resultErr error) {
	var shutdown *boundedShutdown
	if lifecycle, ok := channel.(shutdowner); ok {
		shutdown = newBoundedShutdown(ctx, lifecycle, shutdownTimeout)
	}
	shutdownHandled := false
	defer func() {
		if shutdown == nil || shutdownHandled {
			return
		}
		if err := shutdown.wait(); err != nil {
			resultErr = errors.Join(resultErr, fmt.Errorf("shutdown relay: %w", err))
		}
	}()

	if stdin == nil {
		return errors.New("MCP input is required")
	}
	if stdout == nil {
		return errors.New("MCP output is required")
	}
	if maxRequestsPerMinute <= 0 {
		return errors.New("MCP request budget must be positive")
	}
	requestBudget, err := budget.Open(budgetDir, "mcp-frames", maxRequestsPerMinute, time.Minute)
	if err != nil {
		return fmt.Errorf("open MCP request budget: %w", err)
	}
	defer requestBudget.Close()
	limit, err := frameByteLimit(maxInputBytes)
	if err != nil {
		return fmt.Errorf("configure MCP input limit: %w", err)
	}
	callLimit, err := transportCallLimit(maxConcurrent)
	if err != nil {
		return err
	}

	transportErrors := &firstError{}
	stream := newRequestLimitedStream(
		newBoundedFrameReadCloser(stdin, limit),
		nopWriteCloser{Writer: stdout},
		callLimit,
		mailbox.MaxMCPOutputBytes,
		requestBudget,
	)
	stream.reportError = transportErrors.Record
	reader := newTeardownReadCloser(stream)
	runDone := make(chan struct{})
	if shutdown != nil {
		go func() {
			select {
			case <-ctx.Done():
			case <-reader.Terminated():
			case <-runDone:
			}
			shutdown.start()
		}()
	}

	runErr := New(channel, version).Run(ctx, &mcp.IOTransport{
		Reader: reader,
		Writer: stream,
	})
	close(runDone)
	var shutdownErr error
	if shutdown != nil {
		shutdownErr = shutdown.wait()
		shutdownHandled = true
	}
	return resolveRunError(runErr, shutdownErr, reader.TerminalError(), transportErrors.Err())
}

type boundedShutdown struct {
	baseCtx   context.Context
	lifecycle shutdowner
	timeout   time.Duration
	once      sync.Once
	ctx       context.Context
	done      chan struct{}
	err       error
}

func newBoundedShutdown(ctx context.Context, lifecycle shutdowner, timeout time.Duration) *boundedShutdown {
	return &boundedShutdown{baseCtx: ctx, lifecycle: lifecycle, timeout: timeout, done: make(chan struct{})}
}

func (s *boundedShutdown) start() {
	s.once.Do(func() {
		ctx, cancel := context.WithTimeout(context.WithoutCancel(s.baseCtx), s.timeout)
		s.ctx = ctx
		go func() {
			defer cancel()
			s.err = s.lifecycle.Shutdown(ctx)
			close(s.done)
		}()
	})
}

func (s *boundedShutdown) wait() error {
	s.start()
	select {
	case <-s.done:
		return s.err
	case <-s.ctx.Done():
		select {
		case <-s.done:
			return s.err
		default:
			return s.ctx.Err()
		}
	}
}

// resolveRunError normalizes only the SDK's structured server-closing error
// caused by peer EOF. Errors observed at the transport boundary always win,
// even if the SDK races them with its own close sentinel.
func resolveRunError(runErr, shutdownErr, readTerminalErr, transportErr error) error {
	if shutdownErr != nil {
		shutdownErr = fmt.Errorf("shutdown relay: %w", shutdownErr)
	}
	if transportErr != nil {
		if runErr == nil || errors.Is(runErr, transportErr) {
			return errors.Join(transportErr, shutdownErr)
		}
		return errors.Join(runErr, transportErr, shutdownErr)
	}
	if errors.Is(readTerminalErr, io.EOF) && isSDKServerClosing(runErr) {
		return shutdownErr
	}
	return errors.Join(runErr, shutdownErr)
}

func isSDKServerClosing(err error) bool {
	var rpcErr *jsonrpc.Error
	return errors.As(err, &rpcErr) && rpcErr.Code == sdkServerClosingCode
}

type firstError struct {
	mu  sync.Mutex
	err error
}

func (e *firstError) Record(err error) {
	if err == nil {
		return
	}
	e.mu.Lock()
	if e.err == nil {
		e.err = err
	}
	e.mu.Unlock()
}

func (e *firstError) Err() error {
	e.mu.Lock()
	defer e.mu.Unlock()
	return e.err
}

// teardownReadCloser reports the first terminal read or close. The lifecycle
// watcher uses this signal to stop detached relay work while the MCP SDK is
// still waiting for active handlers to finish.
type teardownReadCloser struct {
	inner       io.ReadCloser
	terminated  chan struct{}
	once        sync.Once
	errMu       sync.Mutex
	terminalErr error
}

func newTeardownReadCloser(inner io.ReadCloser) *teardownReadCloser {
	return &teardownReadCloser{inner: inner, terminated: make(chan struct{})}
}

func (r *teardownReadCloser) Read(p []byte) (int, error) {
	n, err := r.inner.Read(p)
	if err != nil {
		r.signal(err)
	}
	return n, err
}

func (r *teardownReadCloser) Close() error {
	r.signal(nil)
	return r.inner.Close()
}

func (r *teardownReadCloser) Terminated() <-chan struct{} {
	return r.terminated
}

func (r *teardownReadCloser) TerminalError() error {
	r.errMu.Lock()
	defer r.errMu.Unlock()
	return r.terminalErr
}

func (r *teardownReadCloser) signal(err error) {
	r.once.Do(func() {
		r.errMu.Lock()
		r.terminalErr = err
		r.errMu.Unlock()
		close(r.terminated)
	})
}

// transportCallLimit leaves bounded protocol headroom above model execution
// concurrency. Each active model call may have one coalesced retry, while the
// fixed allowance keeps ping, discovery, and immediate busy responses live.
func transportCallLimit(maxConcurrent int) (int, error) {
	if maxConcurrent <= 0 {
		return 0, errors.New("MCP concurrency limit must be positive")
	}
	if maxConcurrent > (math.MaxInt-transportControlHeadroom)/2 {
		return math.MaxInt, nil
	}
	return 2*maxConcurrent + transportControlHeadroom, nil
}

type nopWriteCloser struct {
	io.Writer
}

func (nopWriteCloser) Close() error { return nil }

package mcpserver

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"sync"
	"time"

	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
)

const (
	// This lifetime-wide fail-closed budget deliberately includes notifications
	// and inbound responses. It bounds every peer-controlled message admitted to
	// the SDK outside the separately capped call set, including control floods.
	maxInboundNonCallMessages = 16
	serverBusyCode            = -32000
	serverBusyMessage         = "server busy"
)

var (
	errDuplicateInFlightRequest = errors.New("duplicate in-flight MCP request ID")
	errNonCallBudgetExhausted   = errors.New("inbound MCP non-call message budget exhausted")
	errRequestBudgetExhausted   = errors.New("inbound MCP request budget exhausted")
	errBatchUnsupported         = errors.New("JSON-RPC batches are not supported")
	errOutputTooLarge           = errors.New("MCP output frame exceeds byte limit")
)

// requestLimitedStream enforces admission below the MCP SDK's IOTransport.
// The SDK therefore retains its native connection and private session-update
// hooks, while only bounded, classified frames can reach its dispatch queue.
type requestLimitedStream struct {
	reader *boundedFrameReadCloser
	writer io.WriteCloser

	readMu    sync.Mutex
	writeMu   sync.Mutex
	closeOnce sync.Once

	mu             sync.Mutex
	stopped        bool
	maxInFlight    int
	maxOutputBytes int
	requestBudget  limiter
	pending        map[jsonrpc.ID]struct{}
	responding     int
	nonCalls       int
	readBuffer     []byte
	closeErr       error
	reportError    func(error)
}

type limiter interface {
	Take(time.Time) (bool, error)
}

func newRequestLimitedStream(reader *boundedFrameReadCloser, writer io.WriteCloser, maxInFlight, maxOutputBytes int, requestBudget limiter) *requestLimitedStream {
	return &requestLimitedStream{
		reader:         reader,
		writer:         writer,
		maxInFlight:    maxInFlight,
		maxOutputBytes: maxOutputBytes,
		requestBudget:  requestBudget,
		pending:        make(map[jsonrpc.ID]struct{}),
	}
}

func (s *requestLimitedStream) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	s.readMu.Lock()
	defer s.readMu.Unlock()
	if s.isStopped() {
		s.readBuffer = nil
		return 0, io.EOF
	}

	for len(s.readBuffer) == 0 {
		if s.isStopped() {
			return 0, io.EOF
		}
		frame, err := s.reader.ReadFrame()
		if err != nil {
			s.failRead(err)
			return 0, err
		}
		filtered, busy, err := s.admitFrame(frame)
		if err != nil {
			s.recordError(err)
			return 0, err
		}
		if len(busy) != 0 {
			encoded, err := encodeBusyResponse(busy[0])
			if err != nil {
				s.recordError(err)
				return 0, err
			}
			if _, err := s.writeUntrackedFrame(encoded); err != nil {
				s.recordError(err)
				_ = s.Close()
				return 0, err
			}
		}
		if len(filtered) == 0 {
			continue
		}
		s.readBuffer = filtered
	}

	n := copy(p, s.readBuffer)
	s.readBuffer = s.readBuffer[n:]
	return n, nil
}

func (s *requestLimitedStream) Write(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	if s.isStopped() {
		return 0, io.ErrClosedPipe
	}
	if len(p) > s.maxOutputBytes {
		err := errOutputTooLarge
		s.recordError(err)
		_ = s.Close()
		return 0, err
	}
	ids, err := responseIDs(p)
	if err != nil {
		err = fmt.Errorf("classify MCP output: %w", err)
		s.recordError(err)
		_ = s.Close()
		return 0, err
	}
	s.writeMu.Lock()
	if s.isStopped() {
		s.writeMu.Unlock()
		return 0, io.ErrClosedPipe
	}
	responding := s.beginResponses(ids)
	n, err := s.writer.Write(p)
	if err == nil && n != len(p) {
		err = io.ErrShortWrite
	}
	s.finishResponses(responding)
	s.writeMu.Unlock()
	if err != nil {
		s.recordError(err)
		_ = s.Close()
	}
	return n, err
}

func (s *requestLimitedStream) Close() error {
	s.closeOnce.Do(func() {
		s.stop()
		s.closeErr = errors.Join(s.reader.Close(), s.writer.Close())
		if s.closeErr != nil {
			s.recordError(s.closeErr)
		}
	})
	return s.closeErr
}

func (s *requestLimitedStream) admitFrame(frame []byte) ([]byte, []*jsonrpc.Response, error) {
	// Charge every bounded JSON frame before JSON-RPC decoding. This includes
	// malformed call-shaped objects that the SDK would reject before dispatch.
	allowed, budgetErr := s.requestBudget.Take(time.Now())
	if budgetErr != nil || !allowed {
		return nil, nil, errRequestBudgetExhausted
	}
	message, decoded, err := decodeJSONRPCFrame(frame)
	if err != nil {
		return nil, nil, err
	}
	if !decoded {
		// Let the native SDK return its canonical parse or protocol-version
		// error. A JSON-RPC batch is rejected above before any SDK allocation.
		return frame, nil, nil
	}
	request, isRequest := message.(*jsonrpc.Request)

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.stopped {
		return nil, nil, io.ErrClosedPipe
	}
	if !isRequest || !request.IsCall() {
		if s.nonCalls >= maxInboundNonCallMessages {
			return nil, nil, errNonCallBudgetExhausted
		}
		s.nonCalls++
		return frame, nil, nil
	}
	if _, duplicate := s.pending[request.ID]; duplicate {
		return nil, nil, errDuplicateInFlightRequest
	}
	if len(s.pending)+s.responding >= s.maxInFlight {
		return nil, []*jsonrpc.Response{busyResponse(request.ID)}, nil
	}
	s.pending[request.ID] = struct{}{}
	return frame, nil, nil
}

func decodeJSONRPCFrame(frame []byte) (jsonrpc.Message, bool, error) {
	payload := frame
	if len(payload) > 0 && payload[len(payload)-1] == '\n' {
		payload = payload[:len(payload)-1]
		if len(payload) > 0 && payload[len(payload)-1] == '\r' {
			payload = payload[:len(payload)-1]
		}
	}

	trimmed := bytes.TrimSpace(payload)
	if len(trimmed) > 0 && trimmed[0] == '[' {
		return nil, false, errBatchUnsupported
	}

	message, err := jsonrpc.DecodeMessage(payload)
	if err != nil {
		return nil, false, nil
	}
	return message, true, nil
}

func responseIDs(frame []byte) ([]jsonrpc.ID, error) {
	message, decoded, err := decodeJSONRPCFrame(frame)
	if err != nil {
		return nil, err
	}
	if !decoded {
		return nil, errors.New("invalid JSON-RPC output frame")
	}
	if response, ok := message.(*jsonrpc.Response); ok && response != nil {
		return []jsonrpc.ID{response.ID}, nil
	}
	return nil, nil
}

func busyResponse(id jsonrpc.ID) *jsonrpc.Response {
	return &jsonrpc.Response{
		ID: id,
		Error: &jsonrpc.Error{
			Code:    serverBusyCode,
			Message: serverBusyMessage,
		},
	}
}

func encodeBusyResponse(response *jsonrpc.Response) ([]byte, error) {
	encoded, err := jsonrpc.EncodeMessage(response)
	if err != nil {
		return nil, fmt.Errorf("encode busy response: %w", err)
	}
	return append(encoded, '\n'), nil
}

func (s *requestLimitedStream) beginResponses(ids []jsonrpc.ID) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	count := 0
	for _, id := range ids {
		if _, ok := s.pending[id]; !ok {
			continue
		}
		delete(s.pending, id)
		s.responding++
		count++
	}
	return count
}

func (s *requestLimitedStream) finishResponses(count int) {
	if count == 0 {
		return
	}
	s.mu.Lock()
	s.responding -= count
	if s.responding < 0 {
		s.responding = 0
	}
	s.mu.Unlock()
}

func (s *requestLimitedStream) writeUntrackedFrame(frame []byte) (int, error) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	if s.isStopped() {
		return 0, io.ErrClosedPipe
	}
	n, err := s.writer.Write(frame)
	if err == nil && n != len(frame) {
		err = io.ErrShortWrite
	}
	return n, err
}

func (s *requestLimitedStream) isStopped() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stopped
}

func (s *requestLimitedStream) stop() {
	s.mu.Lock()
	s.stopped = true
	clear(s.pending)
	s.responding = 0
	s.mu.Unlock()
}

func (s *requestLimitedStream) failRead(err error) {
	if !errors.Is(err, io.EOF) {
		s.recordError(err)
	}
}

func (s *requestLimitedStream) recordError(err error) {
	if err != nil && s.reportError != nil {
		s.reportError(err)
	}
}

import unittest

from check_macos_target import check_target


def build_version(version, platform="1"):
    return f"""Load command 10
      cmd LC_BUILD_VERSION
  cmdsize 32
 platform {platform}
    minos {version}
      sdk 15.5
   ntools 1
"""


class DeploymentTargetTest(unittest.TestCase):
    def test_supported_targets(self):
        for version in ("11.0", "12.0", "12.0.0"):
            with self.subTest(version=version):
                self.assertEqual(check_target(build_version(version)), [version])

    def test_rejects_newer_target(self):
        for version in ("12.0.1", "12.1", "14.0", "15.0"):
            with self.subTest(version=version), self.assertRaises(ValueError):
                check_target(build_version(version))

    def test_checks_all_architectures(self):
        with self.assertRaises(ValueError):
            check_target(build_version("12.0") + build_version("15.0"))
        self.assertEqual(
            check_target(build_version("12.0") + build_version("12.0")),
            ["12.0", "12.0"],
        )

    def test_rejects_missing_malformed_or_non_macos_target(self):
        for commands in ("", "not Mach-O", build_version("unknown"),
                         build_version("12.0", platform="2")):
            with self.subTest(commands=commands), self.assertRaises(ValueError):
                check_target(commands)

    def test_legacy_command(self):
        self.assertEqual(check_target("""Load command 9
      cmd LC_VERSION_MIN_MACOSX
  cmdsize 16
  version 12.0
      sdk 15.5
"""), ["12.0"])


if __name__ == "__main__":
    unittest.main()

