package approval

import (
	"crypto/sha256"
	"fmt"
	"strings"
	"testing"
)

func TestSavePendingLargeEscapedBody(t *testing.T) {
	store, err := Open(t.TempDir(), true)
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	body := strings.Repeat("<>", 200_000)
	pending := Pending{MessageID: "large-message", Direction: "outbound", Source: "work", Destination: "personal", Body: body, BodySHA256: fmt.Sprintf("%x", sha256.Sum256([]byte(body)))}
	if err := store.SavePending(pending); err != nil {
		t.Fatal(err)
	}
	loaded, err := store.Pending(pending.MessageID)
	if err != nil {
		t.Fatal(err)
	}
	if loaded != pending {
		t.Fatal("pending body or binding changed")
	}
}

package testutil

import (
	"testing"
	"time"
)

func TestWindowBudgetExpiresAndHandlesClockRollback(t *testing.T) {
	budget := NewWindowBudget(1, time.Minute)
	now := time.Unix(1000, 0)
	first, err := budget.Take(now)
	if err != nil {
		t.Fatal(err)
	}
	second, err := budget.Take(now)
	if err != nil {
		t.Fatal(err)
	}
	if !first || second {
		t.Fatal("budget did not enforce its limit")
	}
	allowed, err := budget.Take(now.Add(time.Minute))
	if err != nil || !allowed {
		t.Fatal("budget did not expire its window")
	}
	allowed, err = budget.Take(now.Add(-time.Minute))
	if err != nil || !allowed {
		t.Fatal("budget did not reset after clock rollback")
	}
}

