package main

import (
	"context"
	"os"
	"sync/atomic"
	"testing"
	"time"
)

func TestSignalCancellationRestoresHandlingBeforeCancel(t *testing.T) {
	signals := make(chan os.Signal, 1)
	var restoreCalls atomic.Int32
	ctx, stop := signalCancellationContext(context.Background(), signals, func() {
		restoreCalls.Add(1)
	})
	t.Cleanup(stop)

	signals <- os.Interrupt
	select {
	case <-ctx.Done():
	case <-time.After(time.Second):
		t.Fatal("first signal did not cancel the context")
	}
	if calls := restoreCalls.Load(); calls != 1 {
		t.Fatalf("restore calls at cancellation = %d, want 1", calls)
	}
	stop()
	if calls := restoreCalls.Load(); calls != 1 {
		t.Fatalf("restore calls after repeated stop = %d, want 1", calls)
	}
}

package strictjson

import "testing"

func TestValidateUniqueKeys(t *testing.T) {
	for _, input := range []string{
		`{"a":1,"a":2}`, `{"a":1,"A":2}`, `{"a":1,"\u0061":2}`,
		`{"K":1,"K":2}`, `{"ſ":1,"S":2}`, `[{"nested":{"a":1,"a":2}}]`,
		`{"a":1} {}`, `{"a":`, `{"a":[}`, ``,
	} {
		if err := ValidateUniqueKeys([]byte(input)); err == nil {
			t.Errorf("accepted ambiguous or invalid JSON: %s", input)
		}
	}
	for _, input := range []string{
		`{"a":1,"b":2}`, `[{"a":1},{"a":2}]`, `{"a":{"a":1}}`,
		`{"a":[null,true,"text",1e9999]}`, `[]`, `null`,
	} {
		if err := ValidateUniqueKeys([]byte(input)); err != nil {
			t.Errorf("rejected valid JSON %s: %v", input, err)
		}
	}
}
